<template><div class="demo-widget universal-demo-widget" :style="style"><span class="widget-kicker">{{ widget.settings.kicker }}</span><b>{{ widget.settings.title }}</b><p>{{ widget.settings.subtitle }}</p><div v-if="widget.settings.progress!==undefined" class="progress-track"><i :style="{width:`${widget.settings.progress}%`}"></i></div></div></template>
<script setup>import{computed}from'vue';const props=defineProps({widget:{type:Object,required:true}});const style=computed(()=>({background:props.widget.settings.background,opacity:props.widget.settings.opacity,borderRadius:`${props.widget.settings.cornerRadius}px`,color:props.widget.settings.color||'#fff'}))</script>
